 kana text := translate(regexp_replace(normalize(coalesce(input,''),NFKC),'[[:space:]・･]','','g'),'ァアィイゥウェエォオカガキギクグケゲコゴサザシジスズセゼソゾタダチヂッツヅテデトドナニヌネノハバパヒビピフブプヘベペホボポマミムメモャヤュユョヨラリルレロヮワヰヱヲンヴヵヶ','ぁあぃいぅうぇえぉおかがきぎくぐけげこごさざしじすずせぜそぞただちぢっつづてでとどなにぬねのはばぱひびぴふぶぷへべぺほぼぽまみむめもゃやゅゆょよらりるれろゎわゐゑをんゔゕゖ');
 result text := ''; part text; token text; pos integer := 1;
begin
 if kana='' or kana !~ '^[ぁ-ゖー]+$' then return ''; end if;
 while pos<=char_length(kana) loop
   if substr(kana,pos,1)='ー' then
     if right(result,1) !~ '[aeiou]' or result='' then return ''; end if;
     result:=result||right(result,1);pos:=pos+1;continue;
   end if;
   part:=null;
   for take in reverse 4..1 loop
     if pos+take-1<=char_length(kana) then
       token:=substr(kana,pos,take);part:=mapping->>token;
       if part is not null then exit; end if;
     end if;
   end loop;
   if part is null then return ''; end if;
   result:=result||part;pos:=pos+char_length(token);
 end loop;
 return result;
end; $fn$;
create function public.set_word_romaji() returns trigger language plpgsql set search_path='' as $fn$
begin new.romaji:=public.reading_romaji(new.reading); return new; end; $fn$;
create trigger words_romaji before insert or update of reading,romaji on public.words for each row execute function public.set_word_romaji();
update public.words set romaji=public.reading_romaji(reading);
commit;
